Bu aşamada, sistemin profesyonel bir sıcak hava istasyonu gibi davranması için **PID (Proportional-Integral-Derivative)** kontrol algoritmasını entegre edeceğiz.

**Önemli Teknik Detay:** Isıtıcılar yavaş tepki veren sistemlerdir. AC Thyristor anahtarları standart Arduino PWM (490Hz) hızında çalışmazlar. Bu yüzden PID çıkışını **"Time Proportional Output" (Zaman Orantılı Çıkış)** yöntemine dönüştüreceğiz. Yani PID örneğin %30 güç istiyorsa, ısıtıcıyı 1 saniyelik bir pencerede 300ms açık, 700ms kapalı tutacaktır.

### Gerekli Kütüphaneler
Lütfen şu kütüphanelerin kurulu olduğundan emin olun:
*   `PID_v1` (by Brett Beauregard)
*   `Adafruit_SSD1306` & `Adafruit_GFX`
*   `max6675`

### Eksiksiz PID Kontrollü Kod

```cpp
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <max6675.h>
#include <PID_v1.h>

// --- PIN TANIMLAMALARI ---
#define MAX6675_SO  10
#define MAX6675_CS  11
#define MAX6675_SCK 12

#define ENC1_CLK    2
#define ENC1_DT     4
#define ENC2_CLK    3
#define ENC2_DT     5

#define HEATER_PIN  7   // Thyristor AC Switch
#define FAN_PIN     6   // IRF520 MOSFET
#define LED_PIN     9   // Indicator LED
#define BUZZER_PIN  A3  // 5V Buzzer
#define REED_PIN    8   // Reed Switch

// OLED Ekran
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

// MAX6675 Nesnesi
MAX6675 thermocouple(MAX6675_SCK, MAX6675_CS, MAX6675_SO);

// --- PID PARAMETRELERİ ---
double Setpoint, Input, Output; 
// Kp: Hızlı tepki, Ki: Hata giderme, Kd: Aşımı önleme (Sönümleme)
// Bu değerler kullanılan ısıtıcıya göre kalibre edilmelidir.
double Kp = 2.0, Ki = 0.5, Kd = 1.0; 
PID myPID(&Input, &Output, &Setpoint, Kp, Ki, Kd, DIRECT);

// Zaman Orantılı Çıkış Penceresi (1 saniye)
int WindowSize = 1000; 
unsigned long windowStartTime;

// Değişkenler
int targetTemp = 200;
int fanSpeed = 150;
bool isAsleep = false;

void setup() {
  Serial.begin(9600);

  pinMode(HEATER_PIN, OUTPUT);
  pinMode(FAN_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(ENC1_CLK, INPUT_PULLUP);
  pinMode(ENC1_DT, INPUT_PULLUP);
  pinMode(ENC2_CLK, INPUT_PULLUP);
  pinMode(ENC2_DT, INPUT_PULLUP);
  pinMode(REED_PIN, INPUT_PULLUP);

  if(!display.begin(SSD1306_SWITCHCLK, 0x3C)) { 
    for(;;); 
  }

  display.clearDisplay();
  display.setTextColor(WHITE);

  // PID Ayarları
  windowStartTime = millis();
  Setpoint = targetTemp;
  myPID.SetOutputLimits(0, WindowSize); // Çıkış 0 ile 1000ms arasında olacak
  myPID.SetMode(AUTOMATIC);
}

void loop() {
  // 1. Sıcaklık Okuma
  Input = thermocouple.readCelsius();
  if (isnan(Input)) {
    // Sensör hatası durumunda güvenlik için her şeyi kapat
    digitalWrite(HEATER_PIN, LOW);
    displayError();
    return;
  }

  // 2. Güvenlik Kontrolü (Reed Switch)
  isAsleep = (digitalRead(REED_PIN) == LOW);

  // 3. Kullanıcı Girişleri
  handleEncoders();
  Setpoint = targetTemp;

  // 4. PID Hesaplama ve Uygulama
  if (isAsleep) {
    Output = 0;
    digitalWrite(HEATER_PIN, LOW);
    analogWrite(FAN_PIN, 60); // Soğutma modu
    digitalWrite(LED_PIN, LOW);
  } else {
    myPID.Compute();

    // Zaman Orantılı Çıkış Uygulaması (Slow PWM)
    unsigned long now = millis();
    if (now - windowStartTime > WindowSize) { 
      windowStartTime = now;
    }
    if (Output > (now - windowStartTime)) {
      digitalWrite(HEATER_PIN, HIGH);
      digitalWrite(LED_PIN, HIGH);
    } else {
      digitalWrite(HEATER_PIN, LOW);
      digitalWrite(LED_PIN, LOW);
    }

    analogWrite(FAN_PIN, fanSpeed);
  }

  // 5. Ekran Güncelleme
  updateDisplay();
}

void handleEncoders() {
  static int lastClk1 = HIGH;
  int clk1 = digitalRead(ENC1_CLK);
  if (clk1 != lastClk1 && clk1 == LOW) {
    if (digitalRead(ENC1_DT) != clk1) targetTemp += 5;
    else targetTemp -= 5;
    targetTemp = constrain(targetTemp, 50, 450);
    tone(BUZZER_PIN, 1000, 10);
  }
  lastClk1 = clk1;

  static int lastClk2 = HIGH;
  int clk2 = digitalRead(ENC2_CLK);
  if (clk2 != lastClk2 && clk2 == LOW) {
    if (digitalRead(ENC2_DT) != clk2) fanSpeed += 15;
    else fanSpeed -= 15;
    fanSpeed = constrain(fanSpeed, 50, 255);
    tone(BUZZER_PIN, 1200, 10);
  }
  lastClk2 = clk2;
}

void updateDisplay() {
  display.clearDisplay();

  // Başlık
  display.setTextSize(1);
  display.setCursor(0,0);
  display.print("PID HOT AIR STATION");

  // Mevcut Sıcaklık
  display.setTextSize(2);
  display.setCursor(0,20);
  display.print("T:"); 
  display.print((int)Input); 
  display.print(" C");

  // Alt Bilgiler
  display.setTextSize(1);
  display.setCursor(0,45);
  display.print("Set: "); display.print(targetTemp); 
  display.print("C  Fan: %"); display.print(map(fanSpeed, 0, 255, 0, 100));

  // PID Güç Yüzdesi (Hata ayıklama için faydalıdır)
  display.setCursor(0,55);
  display.print("Power: %"); display.print(map((int)Output, 0, WindowSize, 0, 100));

  if(isAsleep) {
    display.setCursor(85, 45);
    display.print("[SLEEP]");
  }

  display.display();
}

void displayError() {
  display.clearDisplay();
  display.setCursor(0,20);
  display.setTextSize(1);
  display.print("SENSOR ERROR!");
  display.display();
}
```

### Yapılan Geliştirmeler ve Teknik Açıklamalar:

1. **PID Kütüphanesi Entegrasyonu:** `PID_v1` kütüphanesi kullanılarak sistemin hedef sıcaklığa "sarsıntısız" ulaşması sağlandı. 
   * **Kp (Proportional):** Hata büyükse ısıtıcıyı güçlü açar.
   * **Ki (Integral):** Zamanla biriken küçük hataları gidererek sıcaklığın tam olarak hedefte sabitlenmesini sağlar.
   * **Kd (Derivative):** Hedefe yaklaşırken frenleme yaparak sıcaklığın hedefi aşmasını (overshoot) engeller.
2. **Time Proportional Output (Yavaş PWM):** Isıtıcı elementler çok yavaş sistemler olduğu için standart PWM yerine 1 saniyelik (`WindowSize = 1000`) bir zaman dilimi oluşturuldu. PID'den gelen `Output` değeri, ısıtıcının bu 1 saniyenin ne kadarında açık kalacağını belirler.
3. **Sıcaklık Kararlılığı:** Basit On/Off sistemlerde sıcaklık hedef etrafında ±10°C dalgalanırken, PID ile bu fark ±1°C seviyelerine indirilebilir.
4. **Güvenlik Mekanizması:** `isnan(Input)` kontrolü eklendi. Eğer termokupl kablosu koparsa veya sensör arızalanırsa, Arduino sıcaklığı "NaN" (Not a Number) olarak okur ve ısıtıcıyı anında kapatarak yangın riskini önler.
5. **Ekran Geliştirmesi:** Ekranın altına **"Power: %"** göstergesi eklendi. Bu, PID'nin o an ısıtıcıya ne kadar güç verdiğini görmenizi sağlar (Kalibrasyon yaparken çok işe yarar).

### Kalibrasyon (Tuning) Nasıl Yapılır?
Her ısıtıcı element farklıdır. Eğer sıcaklık çok yavaş yükseliyorsa veya çok fazla dalgalanıyorsa şu sırayı izleyin:
1. Sadece **Kp**'yi artırın; sistem hedefe yaklaşana kadar.
2. Sıcaklık hedefte sabitlenmiyor, biraz altında kalıyorsa **Ki** değerini küçük adımlarla artırın.
3. Sıcaklık hedefi çok aşıp sonra geri düşüyorsa (salınım varsa), **Kd** değerini artırarak sistemi sönümleyin.

**Güvenlik Hatırlatması:** Yüksek voltaj ile çalışıyorsunuz. Devreyi ilk kez çalıştırırken mutlaka bir sigorta kullanın ve ısıtıcıyı gözetim altında tutun.

