```c
/**
 * =====================================================
 * 8-Bit R2R DAC Uygulaması - Raspberry Pi Pico (RP2040)
 * =====================================================
 * 
 * Bu uygulama, RP2040 mikrodenetleyicisinin GPIO pinlerini
 * kullanarak 8-bit R2R ladder DAC devresini kontrol eder.
 * 
 * Devre: Her GPIO pini bir anahtar görevi görür.
 *         MSB'den LSB'ye doğru 8 bitlik dijital değer,
 *         analog voltaja dönüştürülür.
 * 
 * Çıkış Voltajı: VOUT = VREF × (dijital_değer / 256)
 *                 Maksimum: ~3.27V (3.3V × 255/256)
 * 
 * Kullanım: 
 *   - Raspberry Pi Pico SDK kurulu olmalı
 *   - CMake ile build edilmeli
 * =====================================================
 */

#include <stdio.h>
#include "pico/stdlib.h"
#include "r2r_config.h"

// =====================================================
// Global Değişkenler
// =====================================================
static uint8_t current_value = 0;  // Mevcut DAC değeri (0-255)

// =====================================================
// Yardımcı Fonksiyonlar
// =====================================================

/**
 * @brief Belirtilen GPIO pinini HIGH veya LOW yapar.
 * 
 * @param pin   GPIO numarası
 * @param value 1 = HIGH (3.3V), 0 = LOW (GND)
 */
static inline void gpio_set_level(uint8_t pin, uint8_t value) {
    if (value) {
        gpio_put(pin, 1);
    } else {
        gpio_put(pin, 0);
    }
}

// =====================================================
// Ana DAC Fonksiyonları
// =====================================================

/**
 * @brief R2R DAC pinlerini başlatır.
 * 
 * Tüm GPIO pinleri OUTPUT olarak ayarlanır ve LOW (GND)
 * seviyesine çekilir. Bu, devrenin güvenli başlangıç
 * durumunu sağlar.
 */
void r2r_dac_init(void) {
    printf("R2R DAC 8-bit Başlatılıyor...\n");

    // Her pin için OUTPUT moduna ayarla ve LOW yap
    for (int i = 0; i < R2R_RESOLUTION; i++) {
        gpio_init(r2r_pins[i]);
        gpio_set_dir(r2r_pins[i], GPIO_OUT);
        gpio_put(r2r_pins[i], 0);  // Başlangıçta GND
    }

    printf("R2R DAC Hazır! Pinler:");
    for (int i = 0; i < R2R_RESOLUTION; i++) {
        printf(" %d", r2r_pins[i]);
    }
    printf("\n");
}

/**
 * @brief R2R DAC çıkışına dijital değeri uygular.
 * 
 * Bu fonksiyon, 8-bitlik dijital veriyi (0-255) alır ve
 * her biti ilgili GPIO pinine yazar. Devre bu pinlerdeki
 * voltaj seviyelerini analog bir toplamak çıkış üretir.
 * 
 * @param value 0 ile 255 arasında bir değer (8-bit)
 */
void r2r_dac_set(uint8_t value) {
    // Değer aralık kontrolü
    if (value > R2R_MAX_VALUE) {
        value = R2R_MAX_VALUE;
    }

    // Her biti ilgili pine yaz
    for (int i = 0; i < R2R_RESOLUTION; i++) {
        // Bit'i al (MSB'den başlayarak)
        uint8_t bit = (value >> (7 - i)) & 0x01;

        // GPIO pinini ayarla
        gpio_set_level(r2r_pins[i], bit);
    }

    current_value = value;
}

/**
 * @brief Mevcut DAC değerini döndürür.
 * 
 * @return Mevcut dijital değer (0-255)
 */
uint8_t r2r_dac_get(void) {
    return current_value;
}

